dtsPropsFor.ProjectNav:
/** Слаг проекта: из него строятся адреса всех трёх разделов. */
slug: string;
/** Текущий раздел — его ссылка получает класс `here`. */
at: "tasks" | "documents" | "tokens";

dtsPropsFor.Head:
/** Название раздела — рендерится как <h2>. */
title: string;
/** Счётчик рядом с названием, приглушённым текстом. */
count?: React.ReactNode;
/** Действия, прижатые к правому краю. */
children?: React.ReactNode;

dtsPropsFor.Reveal:
/** Подпись действия: видна в покое, при `bare` уходит в title и aria-label. */
label: string;
/** Значок слева от подписи. */
icon?: "plus" | "check" | "x" | "pencil" | "trash" | "filter" | "down" | "right" | "send" | "copy" | "upload" | "move" | "layers" | "ban" | "swap" | "login" | "logout" | "calendar" | "repeat";
/** Окраска действия: `go` — утвердительное, `bad` — разрушительное. */
tone?: "go" | "bad";
/** Раскрыться поверх раскладки, а не раздвинуть её. */
drop?: boolean;
/** Широкая раскрытая панель. */
wide?: boolean;
/** Только значок: подпись уходит в title и aria-label. */
bare?: boolean;
/** Содержимое раскрытой панели — обычно форма. */
children: React.ReactNode;

dtsPropsFor.Icon:
/** Имя глифа из набора. */
name: "plus" | "check" | "x" | "pencil" | "trash" | "filter" | "down" | "right" | "send" | "copy" | "upload" | "move" | "layers" | "ban" | "swap" | "login" | "logout" | "calendar" | "repeat";
/** Сторона квадрата в пикселях. По умолчанию 14. */
size?: number;

dtsPropsFor.ConfirmButton:
/** Подпись кнопки. */
children: React.ReactNode;
/** Вопрос в нативном confirm(): отмена гасит submit формы. */
message: string;
/** Классы кнопки. По умолчанию `act bad`. */
className?: string;
/** Подпись для кнопки без текста — уходит в title и aria-label. */
label?: string;
